private void mnuItemPrint1_Click(object sender, EventArgs e)
{
    SystemManager.Report.frmReportView frm = new SystemManager.Report.frmReportView(dtbData, "Report/StudentManager/Report/Mau_TN_LaiXe.repx", false);
  //  frm.SetParameter("pMonth", "THÁNG " + dtmMonth.EditValueDateTime.Value.Month + " NĂM " + dtmMonth.EditValueDateTime.Value.Year);

    //frm.SetParameter("pScience", uScienceCourseTypeLevel.sc);
    // List khóa đã chọn khi tìm kiếm (EditValue dạng ;C1K08;C1K09; -> C1K08, C1K09)
    string strCourseList = "";
    if (uScienceCourseTypeLevel.CourseIDEditValue != null)
    {
        strCourseList = uScienceCourseTypeLevel.CourseIDEditValue.ToString().Trim(';');
        strCourseList = strCourseList.Replace(";", ", ");
    }
    frm.SetParameter("pCourse", strCourseList);
    //frm.SetParameter("pTrainingType", uScienceCourseTypeLevel.TrainingTypeEditValue);
    //frm.SetParameter("pTrainingLevel", uScienceCourseTypeLevel.TrainingLevelName);
    frm.Show();
}

    frm.SetParameter("pCourse", strCourseList);

    // List lớp Distinct từ dữ liệu (ClassName ngăn cách dấu ,)
    string strClassList = "";
    if (dtbData != null && dtbData.Columns.Contains("ClassName"))
    {
        Hashtable hstClass = new Hashtable();
        foreach (DataRow drw in dtbData.Rows)
        {
            if (drw["ClassName"] == null || drw["ClassName"] == DBNull.Value)
                continue;
            string strClassName = drw["ClassName"].ToString().Trim();
            if (strClassName == "" || hstClass.ContainsKey(strClassName))
                continue;
            hstClass.Add(strClassName, strClassName);
            if (strClassList != "")
                strClassList += ", ";
            strClassList += strClassName;
        }
    }
    frm.SetParameter("pClass", strClassList);

    //frm.SetParameter("pTrainingType", uScienceCourseTypeLevel.TrainingTypeEditValue);
    //frm.SetParameter("pTrainingLevel", uScienceCourseTypeLevel.TrainingLevelName);
    frm.Show();
}

